  'Fehu': { k:'abundancia', a:'In love, affection is shown through generosity and caring for what you already have; avoid measuring the relationship in terms of gain.', t:'At work and in money, resources or income arrive; manage them in an orderly way so they multiply.', i:'Loss, uncontrolled spending, or fear of scarcity. Look at where you are wasting energy or money.' },
  'Uruz': { k:'life force', a:'In love, there is desire, vitality, and the courage to take a step; be careful not to impose yourself.', t:'At work you have the energy for a demanding challenge; use it with consistency.', i:'Weakness, exhaustion, or misdirected strength. Rest, look after your health, and avoid charging ahead blindly.' },
  'Thurisaz': { k:'threshold and defense', a:'In love there may be a clash or a barrier; set boundaries without hurting anyone and think before you react.', t:'At work an obstacle or confrontation appears; analyze before acting and protect your interests.', i:'Impulsiveness, needless conflict, or vulnerability. Beware of anger and hasty decisions.' },
  'Ansuz': { k:'a message', a:'In love, an honest conversation or an important message clarifies the bond.', t:'At work, communication, a meeting, or the advice of someone experienced opens an opportunity.', i:'Misunderstandings, confusing messages, or advice you shouldn’t follow. Verify before you believe or reply.' },
  'Raidho': { k:'the path', a:'In love, the bond moves forward or gets set in motion: a trip together or a new step in the relationship.', t:'At work, a trip, a move, or a project moves forward; plan your route and your timing.', i:'Delays, detours, or lack of direction. Rethink your path before going on.' },
  'Kenaz': { k:'light and creativity', a:'In love, passion ignites, or clarity about what you feel.', t:'At work, a brilliant idea or a skill gets recognized; a good time to create and learn.', i:'A lack of ideas, a closing door, or a flame going out. Look for a new source of inspiration.' },
  'Gebo': { k:'fair exchange', a:'In love there is reciprocity: giving and receiving in balance strengthens the union.', t:'At work, a partnership or a fair deal benefits both sides.', i:null },
  'Wunjo': { k:'joy', a:'In love, harmony, tenderness, and a season of shared well-being.', t:'At work, a good atmosphere, achievements, and recognition; celebrate with your team.', i:'Dissatisfaction or a joy that is delayed. Don’t force happiness: take care of the basics.' },
  'Hagalaz': { k:'a necessary break', a:'In love, a crisis shakes what was stagnant; the truth sets in order what comes next.', t:'At work, an unexpected change or a setback; rebuild calmly.', i:null },
  'Nauthiz': { k:'need and patience', a:'In love, you feel a lack; ask for what you need without demanding.', t:'At work, limited resources: set priorities and work patiently.', i:null },
  'Isa': { k:'a pause', a:'In love there is coldness or waiting; don’t push, let the emotions thaw.', t:'At work, a project stalls; use the pause to plan.', i:null },
  'Jera': { k:'the harvest', a:'In love, sustained effort bears fruit: a relationship that matures or a commitment.', t:'At work, the results of what you sowed arrive.', i:null },
  'Eihwaz': { k:'resistance', a:'In love, the bond is tested and strengthened through steadiness.', t:'At work, perseverance in the face of change; your stability protects you.', i:null },
  'Perthro': { k:'mystery', a:'In love, there are secrets or a surprise; let things reveal themselves over time.', t:'At work, chance or hidden information may change the plan; stay flexible.', i:'Secrets that weigh on you, adverse chance, or missing information. Avoid gambling without knowing.' },
  'Algiz': { k:'protection', a:'In love, there is protection and support; trust your intuition around someone new.', t:'At work you are sheltered and can defend your position calmly.', i:'Vulnerability or carelessness. Reinforce your boundaries and don’t expose yourself needlessly.' },
  'Sowilo': { k:'success', a:'In love, brightness, warmth, and a luminous stage.', t:'At work, success and visibility; a time to show your achievements.', i:null },
  'Tiwaz': { k:'justice and courage', a:'In love, honesty and commitment; stand up for what is fair in the relationship.', t:'At work, fair leadership and discipline; act with honor.', i:'Injustice, lack of courage, or misdirected energy. Check whether you are fighting for the right thing.' },
  'Berkano': { k:'a new beginning', a:'In love, something is born or is being tended with tenderness: a new relationship or a family stage.', t:'At work, a project in the making calls for patient care.', i:'Stagnation, neglect of what is growing, or family problems. Nurture what matters.' },
  'Ehwaz': { k:'cooperation', a:'In love, trust and teamwork: you move forward together.', t:'At work, a reliable partner or team speeds your progress.', i:'Distrust, uneven pace, or lack of agreement. Align expectations.' },
  'Mannaz': { k:'you and others', a:'In love, self-knowledge and mutual support.', t:'At work, collaboration and recognition of your talents.', i:'Isolation, selfishness, or conflicts with others. Own your part.' },
  'Laguz': { k:'intuition', a:'In love, emotions flow; trust what you feel.', t:'At work, intuition and sensitivity guide a decision.', i:'Emotional confusion, fear, or blockage. Don’t decide out of anxiety.' },
  'Ingwaz': { k:'gestation', a:'In love, one cycle is completing and another is preparing; patience.', t:'At work, a project is maturing from within.', i:null },
