window.PM_RUNAS_X2 = {"Fehu": {"c": "Make a simple budget this week and decide where you’ll put your energy and your money.", "q": "Am I investing my energy in what I truly want to see grow?", "af": "I value what I have and care for it so it can grow.", "p": "you once received or lost resources that today shape your relationship with money and security", "f": "a stage is approaching where what you tend today will multiply", "ic": "Before spending or promising, take inventory of what you already have."}, "Uruz": {"c": "Set yourself a physical or practical challenge that suits you and keep it for seven days.", "q": "What challenge scares me and, at the same time, makes me feel alive?", "af": "I have the strength I need for what is coming.", "p": "you went through a trial that made you stronger, even if you didn’t see it that way at the time", "f": "a moment that calls for courage and health is coming: take care of yourself from now on", "ic": "Prioritize rest, food, and movement before launching into anything new."}, "Thurisaz": {"c": "Before reacting, wait twenty-four hours and write down what you truly want to protect.", "q": "What limit do I need to set without hurting anyone?", "af": "I set boundaries firmly and calmly.", "p": "a confrontation or an obstacle shaped the way you defend yourself today", "f": "soon you may run into a barrier: see what it’s protecting you from before charging at it", "ic": "Count to ten; the impulse driving you today may not be your best counselor."}, "Ansuz": {"c": "Seek out that pending conversation today, or ask advice from someone you admire.", "q": "What message am I avoiding saying or hearing?", "af": "I listen attentively and speak truthfully.", "p": "you received words or advice that still resonate within you", "f": "a key piece of news, idea, or conversation will arrive; stay alert", "ic": "Check the facts before believing a message; ask for it to be repeated if you have doubts."}, "Raidho": {"c": "Plan the next step on your path and put a date on it in your calendar.", "q": "Am I heading in the direction I truly chose?", "af": "I move forward at my own pace and with a clear direction.", "p": "a journey or a change of course brought you here", "f": "a movement is opening up: a trip, a move, or a new direction", "ic": "Before going on, check the map: is your destination still the same?"}, "Kenaz": {"c": "Spend thirty minutes on something creative without trying to make it perfect.", "q": "What idea wants to be lit up now?", "af": "My creativity lights my way.", "p": "a creative spark or a piece of knowledge opened doors for you", "f": "clarity and inspiration are coming: get a notebook ready", "ic": "Look for a new source of inspiration: a place, a person, a book."}, "Gebo": {"c": "Do a generous act today without expecting anything in return, and notice how you feel.", "q": "Do I give and receive in balance in my relationships?", "af": "I give and receive with gratitude.", "p": "an exchange or a gift marked an important relationship", "f": "a partnership or a fair agreement is drawing near", "ic": "Check whether you are giving too much or receiving too little; rebalance with a conversation."}, "Wunjo": {"c": "Share a piece of good news today and celebrate it with someone close.", "q": "What would make me feel at peace and genuinely happy this week?", "af": "I allow myself to feel joy without guilt.", "p": "a time of well-being left a luminous mark on you", "f": "a time of harmony and recognition is approaching", "ic": "Don’t force joy: start with the basics (sleep, food, company)."}, "Hagalaz": {"c": "Accept what you can’t control and focus on rebuilding what you can.", "q": "What needs to break so that something better can be born?", "af": "After the storm, I rebuild with greater wisdom.", "p": "a shock forced you to change course, and it has passed", "f": "an unexpected change may arrive: protect what is essential and stay calm", "ic": "Avoid big decisions while the upheaval lasts; secure the basics first."}, "Nauthiz": {"c": "Identify a real need you have put off and meet it with one small step.", "q": "What do I truly need, beyond what I want?", "af": "With patience, I overcome every limitation.", "p": "you went through scarcity and learned to manage what you had", "f": "a period of adjustment is coming: plan and prioritize", "ic": "Postpone non-urgent expenses or commitments and protect your energy."}, "Isa": {"c": "Make the most of the pause: rest, reflect, and don’t make hasty decisions.", "q": "What emotion do I have frozen that I need to look at calmly?", "af": "I accept the pause as part of the process.", "p": "a period of stagnation taught you to wait", "f": "there will be a time of waiting; it’s not a setback, it’s preparation", "ic": "No pressure or ultimatums: give time and space."}, "Jera": {"c": "Recognize and celebrate a result your perseverance has already produced.", "q": "What did I sow a long time ago that is already bearing fruit?", "af": "I harvest what I patiently sowed.", "p": "the effort of another time supports you today", "f": "medium-term results are coming if you stay consistent", "ic": "Patience: good things ripen in their own cycle, not yours."}, "Eihwaz": {"c": "Strengthen your foundation: habits, routine, support; something to hold you up in the storm.", "q": "What keeps me steady when everything changes?", "af": "I am firm and flexible like a yew.", "p": "a test of endurance taught you to hold yourself up", "f": "a period of transition is coming in which your perseverance will be key", "ic": "Avoid shortcuts; choose what lasts, even if it’s slower."}, "Perthro": {"c": "Let something reveal itself without forcing it; note signs and coincidences for a week.", "q": "What part of my destiny do I prefer not to look at yet?", "af": "I trust in what is revealed in its own time.", "p": "something hidden became clear and changed how you see things", "f": "something hidden will be revealed today; keep an open mind", "ic": "Don’t take for granted what is still unclear; wait for more information."}, "Algiz": {"c": "Surround yourself with people and places that look after you; look after your boundaries too.", "q": "What or who protects me, and what do I need to protect?", "af": "I am protected and I am learning to protect myself.", "p": "someone or something protected you when you needed it most", "f": "a stage of shelter and reliable allies is coming", "ic": "Be careful not to expose yourself too much; choose wisely whom you trust."}, "Sowilo": {"c": "Show yourself: share an achievement, take your place with confidence.", "q": "Where am I hiding my light?", "af": "My light shines without asking permission.", "p": "a victory or success still gives you energy", "f": "a moment of success and clarity is approaching: make the most of it", "ic": "Don’t burn out: too much enthusiasm is tiring too; pace yourself."}, "Tiwaz": {"c": "Act with honor: keep a pending promise or stand up for what is just.", "q": "What cause is worth striving and taking risks for?", "af": "I act with courage and fairness.", "p": "an act of courage or a just conflict defined you", "f": "a moment of noble struggle or firm decision is coming", "ic": "Take care that courage doesn’t turn into stubbornness; make sure your cause is just."}, "Berkano": {"c": "Look after something just being born: a project, a habit, a relationship.", "q": "What new beginning deserves my care now?", "af": "I nurture what is new with tenderness and consistency.", "p": "something was born in your life and still marks you", "f": "there will be a new beginning, a birth, or a renewal", "ic": "Don’t demand results from what is just being born; it needs time and care."}, "Ehwaz": {"c": "Strengthen an alliance built on trust: ask for help or help someone.", "q": "With whom do I move forward best, and how can I care for that bond?", "af": "I move forward with confidence and companionship.", "p": "a traveling companion pushed you forward when you needed it", "f": "a gradual advance arrives, often alongside someone you trust", "ic": "If something isn’t moving forward, check your communication with the person beside you."}, "Mannaz": {"c": "Look at yourself honestly: how do others see you, and how do you see yourself?", "q": "What role do I play in my group, and is it the one I want?", "af": "I am part of something, and I am myself.", "p": "your relationships shaped your identity", "f": "it is time to cooperate and see yourself clearly", "ic": "Avoid comparing yourself; your worth doesn’t depend on the role others give you."}, "Laguz": {"c": "Listen to your intuition: keep a dream or hunch journal this week.", "q": "What is my intuition telling me that my mind is still arguing with?", "af": "I trust my intuition and flow.", "p": "a deep emotion or an intuition guided you", "f": "sensitivity and intuition are growing: take care of your rest", "ic": "Take care not to be swept away by emotion: breathe before deciding."}, "Ingwaz": {"c": "Finish a pending task: that seed is ready to bear fruit.", "q": "What process am I about to complete?", "af": "I close cycles with calm and gratitude.", "p": "a stage was completed and left something in you", "f": "the close of one cycle and the preparation of another is approaching", "ic": "Don’t open new fronts until you close the current one."}, "Dagaz": {"c": "Choose a positive change and make it today: the moment of clarity is now.", "q": "What part of my life is ready to dawn?", "af": "I awaken to a new stage with hope.", "p": "a transformation changed you for the better", "f": "a luminous change is coming, a before and an after", "ic": "Don’t stay in the waiting; change comes when you act."}, "Othala": {"c": "Honor your roots: call a relative or tidy something in your home.", "q": "What did I inherit that I want to keep, and what do I want to leave behind?", "af": "I honor my roots and build my home.", "p": "your family or your home was the foundation of who you are today", "f": "it is time to strengthen your home, family, or assets", "ic": "Don’t cling to what you inherited if it no longer serves you; choose what to keep."}};
window.PM_ICHING_X2 = {"1": {"k": "creative force", "c": "Act with constancy and integrity, without imposing yourself.", "q": "What do I want to begin with all my commitment?"}, "2": {"k": "receptivity", "c": "Support, follow, and let things ripen.", "q": "What do I gain if I stop wanting to direct everything?"}, "3": {"k": "difficult beginnings", "c": "Put things in order step by step and ask for help.", "q": "What small first step can I take today?"}, "4": {"k": "learning", "c": "Ask with humility and listen once.", "q": "What do I still need to learn in order to decide well?"}, "5": {"k": "patient waiting", "c": "Nourish yourself, prepare, and don’t force the moment.", "q": "How can I use this waiting to my advantage?"}, "6": {"k": "conflict", "c": "Seek an agreement and avoid taking it to the extreme.", "q": "What do I really gain by winning this argument?"}, "7": {"k": "collective discipline", "c": "Organize your effort around a clear goal.", "q": "Am I clear on why I am fighting?"}, "8": {"k": "sincere union", "c": "Join those who share your direction soon.", "q": "Who am I truly willing to commit to?"}, "9": {"k": "small restraints", "c": "Insist gently; drops fill the glass.", "q": "What small detail is holding me back?"}, "10": {"k": "prudent conduct", "c": "Move forward with courtesy, even in the face of difficulty.", "q": "How can I be firm without being abrupt?"}, "11": {"k": "peace and prosperity", "c": "Use the harmony to build and share.", "q": "What can I build while the moment is favorable?"}, "12": {"k": "stagnation", "c": "Hold to your principles and wait for better times.", "q": "What is worth preserving while nothing flows?"}, "13": {"k": "community", "c": "Look for allies with shared ideals and act in the light.", "q": "With whom do I truly share my values?"}, "14": {"k": "abundance", "c": "Share what you have and stay humble.", "q": "How do I use what I have with generosity?"}, "15": {"k": "modesty", "c": "Be humble; balance things and give each person their due.", "q": "Where would it help me to be more modest?"}, "16": {"k": "enthusiasm", "c": "Spread good spirits, but plan before you leap.", "q": "Does my enthusiasm have a plan behind it?"}, "17": {"k": "following the other", "c": "Follow what deserves following, with judgment.", "q": "Whom or what do I follow, and why?"}, "18": {"k": "what needs repair", "c": "Patiently fix what has gone wrong.", "q": "What inheritance or habit do I need to repair?"}, "19": {"k": "coming together", "c": "Take advantage of the momentum that’s coming; don’t let it pass.", "q": "What is approaching me that I should receive?"}, "20": {"k": "contemplation", "c": "Observe calmly before acting.", "q": "What do I see from afar that I couldn’t make out up close?"}, "21": {"k": "crossing obstacles", "c": "Resolve with firmness whatever blocks progress.", "q": "What obstacle do I need to face once and for all?"}, "22": {"k": "grace and form", "c": "Look after the form, but don’t sacrifice the substance.", "q": "Am I caring for the image or the substance?"}, "23": {"k": "disintegration", "c": "Hold on to what’s essential while the old falls away.", "q": "What structure no longer holds?"}, "24": {"k": "the return", "c": "Return to what is essential; a new cycle begins.", "q": "What do I want to return to?"}, "25": {"k": "innocence", "c": "Act naturally and without ulterior motives.", "q": "What would I do if I weren’t thinking about the outcome?"}, "26": {"k": "accumulated strength", "c": "Build up experience and wait so you can act with weight.", "q": "What am I accumulating that will prove useful?"}, "27": {"k": "nourishment", "c": "Watch what you eat, read, and say: it shapes you.", "q": "What am I feeding on?"}, "28": {"k": "excessive burden", "c": "Strengthen the foundation before carrying more.", "q": "What weight exceeds my support?"}, "29": {"k": "the abyss and danger", "c": "Stay calm and sincere in difficulty.", "q": "How do I get through this without losing my center?"}, "30": {"k": "clarity", "c": "Be clear and lean on what illuminates.", "q": "What do I need to see in a clearer light?"}, "31": {"k": "mutual attraction", "c": "Open your heart with sincerity and without calculation.", "q": "What attracts me, and why?"}, "32": {"k": "duration", "c": "Persevere in what is worthwhile; constancy creates stability.", "q": "What is worth sustaining over time?"}, "33": {"k": "retreat", "c": "Withdrawing in time is wise, not cowardly.", "q": "What is best left behind now?"}, "34": {"k": "great power", "c": "Use your strength with fairness and without arrogance.", "q": "Is my strength in the service of what is right?"}, "35": {"k": "progress", "c": "Move forward and show yourself; recognition will come.", "q": "What am I ready to show?"}, "36": {"k": "the hidden light", "c": "Protect your light and wait without losing hope.", "q": "What part of me should I protect for now?"}, "37": {"k": "the family and the clan", "c": "Look after roles and affection at home.", "q": "How do I look after my home and those close to me?"}, "38": {"k": "opposition", "c": "Look for common ground amid the differences.", "q": "What unites us despite what separates us?"}, "39": {"k": "obstruction", "c": "Stop, review, and seek help from someone who knows.", "q": "What is this obstacle teaching me?"}, "40": {"k": "liberation", "c": "Resolve and forgive; start over without burdens.", "q": "What tension am I freeing myself from?"}, "41": {"k": "decrease", "c": "Cut back the superfluous and keep what is essential.", "q": "What can I give up without losing what matters?"}, "42": {"k": "increase", "c": "Take advantage of the favorable momentum and be generous.", "q": "How do I share this growth?"}, "43": {"k": "the decisive breakthrough", "c": "Tell the truth firmly, without violence.", "q": "What do I need to clear up once and for all?"}, "44": {"k": "the unexpected encounter", "c": "Be careful whom you cross paths with: not everything that arrives is good for you.", "q": "What is presenting itself to me, and how do I evaluate it?"}, "45": {"k": "gathering together", "c": "Come together around a common goal and a good leader.", "q": "What brings us together, and how do we look after it?"}, "46": {"k": "gradual ascent", "c": "Climb patiently, step by step.", "q": "What concrete step brings me closer to the summit?"}, "47": {"k": "oppression", "c": "Keep your integrity when resources are lacking.", "q": "What holds me up when everything is lacking?"}, "48": {"k": "the well", "c": "Look after the well that feeds everyone and keep it clean.", "q": "What inner resource do I need to clear or deepen?"}, "49": {"k": "revolution", "c": "Change with timing and backing; not on impulse.", "q": "Am I ready for a fundamental change?"}, "50": {"k": "the cauldron", "c": "Transform what you have into something that nourishes others.", "q": "What am I cooking that is worth sharing?"}, "51": {"k": "the thunder", "c": "Stay calm in the face of fright: it passes and leaves clarity.", "q": "What shock woke me up?"}, "52": {"k": "stillness", "c": "Stop in time and quiet your mind.", "q": "Where do I need to say stop?"}, "53": {"k": "gradual development", "c": "Move forward without haste; what is solid grows slowly.", "q": "Do I respect the natural pace of this process?"}, "54": {"k": "union without a foundation", "c": "Be careful with commitments made before they have matured.", "q": "Does this union have a solid foundation?"}, "55": {"k": "abundance", "c": "Enjoy the boom without forgetting that it’s fleeting.", "q": "How can I make the most of my fullness without clinging?"}, "56": {"k": "the traveler", "c": "Be cautious and respectful in the unknown.", "q": "How do I adapt without losing my essence?"}, "57": {"k": "the gentle influence", "c": "Persevere with gentleness; softness penetrates.", "q": "Where does gentleness achieve more than force?"}, "58": {"k": "serene joy", "c": "Share the joy and seek sincere conversation.", "q": "What conversation delights and nourishes me?"}, "59": {"k": "dispersion", "c": "Dissolve rigidity and resentment with openness.", "q": "What inner barrier can I dissolve?"}, "60": {"k": "limitation", "c": "Set healthy limits; neither excess nor rigidity.", "q": "What boundary is it good for me to set?"}, "61": {"k": "inner truth", "c": "Act from sincerity; trust opens doors.", "q": "Am I true to what I really feel?"}, "62": {"k": "the small things that matter", "c": "Attend to the details, without expecting too much.", "q": "What detail deserves my attention?"}, "63": {"k": "after completion", "c": "Keep your guard up even if everything seems resolved.", "q": "What could fall into disorder if I relax?"}, "64": {"k": "before completion", "c": "Prepare well; there is little left before the close.", "q": "What do I need to reach the end?"}};

window.PM_ICHING_LINE_TXT = {
  1:{ 9:'Line 1 (the beginning), yang changing: there is an initial impulse in the matter of {k}. Don’t rush: what starts now can’t be seen yet and needs care.', 6:'Line 1 (the beginning), changing yin: on the subject of {k}, a passive or doubtful attitude is about to take a turn. Move gently but with intention.' },
  2:{ 9:'Line 2 (your close circle), changing yang: on the subject of {k}, your inner circle asks you to take a more active and clear stance.', 6:'Line 2 (your inner circle), changing yin: on the subject of {k}, what happens at home or with your own people is transforming; listen before you decide.' },
  3:{ 9:'Line 3 (the threshold), yang changing: in the matter of {k} you are at a point of tension; excess drive is the risk. Slow down and review.', 6:'Line 3 (the threshold), changing yin: on the subject of {k}, a doubt or discouragement holds you back right at the crossing; seek support instead of isolating yourself.' },
  4:{ 9:'Line 4 (approaching power), changing yang: on the subject of {k}, there is a decision that brings you closer to people of influence; act with prudence.', 6:'Line 4 (approaching power), changing yin: on the subject of {k}, sensitivity and tact open the way for you with those who decide.' },
  5:{ 9:'Line 5 (the seat of command), yang changing: in the matter of {k} you are at your point of greatest influence; lead with balance and without arrogance.', 6:'Line 5 (the seat of command), changing yin: on the subject of {k}, gentleness occupies the central place; governing with humility is the key.' },
  6:{ 9:'Line 6 (the end), changing yang: on the subject of {k}, excess pushes things to the limit; it is time to close and not push any further.', 6:'Line 6 (the end), changing yin: on the subject of {k}, a cycle is dissolving; let go with gratitude so the next one can open.' }
};
