window.PM_SN_QTIP = function (q) {
  if (!q) return 'Tip: write a specific question before choosing the card; the answer will be more precise.';
  if (/^\s*[¿]?\s*(cu[aá]ndo|por qu[eé]|c[oó]mo|qu[eé]|qui[eé]n|d[oó]nde|cu[aá]l|cu[aá]nto)/i.test(q)) return 'Note: yes or no works best with closed questions. You can rephrase, for example: “Should I…?” or “Is it a good time to…?”.';
  return '';
};

