/* Portal Místico — Tarot sí o no, Runas e I Ching */
(function () {
  'use strict';
  var main = document.querySelector('[data-tool]'); if (!main) return;
  var tool = main.getAttribute('data-tool');
  var $ = function (id) { return document.getElementById(id); };
  var SITE = 'https://elportalmistico.com/juegos/';
  function rnd(n) { var a = new Uint32Array(1); (window.crypto || window.msCrypto).getRandomValues(a); return a[0] % n; }
  function shuffle(arr) { var a = arr.slice(); for (var i = a.length - 1; i > 0; i--) { var j = rnd(i + 1), t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function track(n) { if (window.gtag) try { gtag('event', n); } catch (e) {} }
  function share(text, url, btn) {
    if (navigator.share) { navigator.share({ title: document.title, text: text, url: url }).catch(function () {}); return; }
    if (navigator.clipboard) navigator.clipboard.writeText(text + ' ' + url).then(function () { btn.textContent = '✓ Copied'; setTimeout(function () { btn.textContent = '📤 Share'; }, 2000); });
  }
  function scrollTo(el) { setTimeout(function () { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 60); }

  /* Una consulta al día por oráculo: el resultado se guarda hasta medianoche. */
  function pmDay() { var d = new Date(); return d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate(); }
  function pmLoad(k) { try { var r = JSON.parse(localStorage.getItem('pm-daily-' + k) || 'null'); return r && r.day === pmDay() ? r : null; } catch (e) { return null; } }
  function pmSave(k, html, txt, url) { try { localStorage.setItem('pm-daily-' + k, JSON.stringify({ day: pmDay(), html: html, txt: txt, url: url })); } catch (e) {} }
  function pmLeft() { var n = new Date(), m = new Date(n.getFullYear(), n.getMonth(), n.getDate() + 1), t = Math.ceil((m - n) / 60000); return Math.floor(t / 60) + ' h ' + (t % 60) + ' min'; }
  function pmLock(againId) {
    var a = $(againId); if (!a) return;
    var p = document.createElement('p'); p.className = 'ca-note'; p.style.textAlign = 'center';
    p.innerHTML = '✦ Today’s reading is already done: the oracle has spoken, and repeating it takes away its strength. You can consult again in <strong>' + pmLeft() + '</strong>.';
    a.parentNode.replaceChild(p, a);
  }
  function pmRestore(out, sv, againId, hide) {
    out.innerHTML = sv.html; out.hidden = false; pmLock(againId);
    var sh = $('caShare'); if (sh) sh.addEventListener('click', function () { share(sv.txt, sv.url, this); });
    hide.forEach(function (e) { if (e) e.style.display = 'none'; });
  }

  /* ====================== TAROT SÍ O NO ====================== */
  if (tool === 'tarot-sn') {
    var CARDS = window.PM_TAROT_SN, spread = $('snSpread'), out = $('caResult'), q = $('snQ');
    var ANS = {
      si: ['YES', 'ca-yes', ' is a favorable card: it speaks of ', '. The energies support what you ask; take the step with confidence.'],
      no: ['NO', 'ca-no', ' speaks of ', '. For now it isn’t the time: it’s best to wait, let go, or change your approach.'],
      quizas: ['MAYBE', 'ca-maybe', ' speaks of ', '. The answer depends on you and how you act; ask again later.']
    };
    function deal() {
      var deck = shuffle(CARDS).slice(0, 7);
      out.hidden = true; out.innerHTML = '';
      spread.innerHTML = deck.map(function (c, i) { return '<button type="button" class="sn-card" data-i="' + i + '" aria-label="Choose card ' + (i + 1) + '" style="--r:' + ((i - 3) * 6) + 'deg"><img src="tarot-game/assets/celestial-tarot-back.webp" alt="" width="120" height="191"></button>'; }).join('');
      spread.classList.remove('sn-done');
      spread.querySelectorAll('.sn-card').forEach(function (b) {
        b.addEventListener('click', function () {
          if (spread.classList.contains('sn-done')) return;
          spread.classList.add('sn-done'); b.classList.add('sn-picked');
          var c = deck[+b.getAttribute('data-i')], rev = rnd(10) < 3, key = rev ? (window.PM_SN_REV || {})[c[2]] || c[2] : c[2], A = ANS[key];
          var qtxt = q.value.trim(), dom = null; (window.PM_SN_DOMINIOS || []).concat(window.PM_SN_DOMINIOS_X || []).forEach(function (d) { if (!dom && d.re.test(qtxt)) dom = d; });
          var img = new Image(); img.src = 'tarot-game/assets/' + c[1] + '.webp';
          setTimeout(function () {
            out.innerHTML = '<div class="sn-res">' + (q.value.trim() ? '<p class="sn-q">“' + esc(q.value.trim()) + '”</p>' : '') +
              '<img class="sn-face" src="' + img.src + '" alt="' + esc(c[0]) + (rev ? ' (reversed)' : '') + '" width="220" height="351"' + (rev ? ' style="transform:rotate(180deg)"' : '') + '>' +
              '<div class="sn-ans ' + A[1] + '">' + A[0] + '</div><h2>' + esc(c[0]) + (rev ? ' <small>(reversed)</small>' : '') + '</h2>' +
              (rev ? '<p>' + esc(c[0]) + ' came up reversed and nuances the answer: it speaks of ' + c[3] + ', but with delays, doubts, or something that isn’t ready yet. The answer may be only half “yes” or “no”.</p>' : '<p>' + esc(c[0]) + A[2] + c[3] + A[3] + '</p>') +
              (dom ? '<p>' + dom[key] + '</p>' : '') +
              '<p class="rn-extra"><em>Next step:</em> ' + (function () { var t = (window.PM_SN_TIPS || {})[key] || []; return t.length ? t[rnd(t.length)] : ''; })() + '</p>' +
              (window.PM_SN_QTIP && window.PM_SN_QTIP(qtxt) ? '<p class="ca-note">' + window.PM_SN_QTIP(qtxt) + '</p>' : '') +
              '<div class="ca-actions"><button type="button" class="ca-btn2" id="snAgain">🔄 Ask another question</button><button type="button" class="ca-btn2" id="caShare">📤 Share</button></div>' +
              '<p class="ca-more">Want a deeper reading? <a href="tarot.html">Do a full tarot spread →</a></p></div>';
            out.hidden = false; scrollTo(out);
            var shTxt = 'The tarot answered me ' + A[0] + ' with ' + c[0] + (rev ? ' (reversed)' : '') + '. Ask yours too, free:';
            pmLock('snAgain'); pmSave('sn', out.innerHTML, shTxt, SITE + 'tarot-si-o-no.html'); q.parentNode.style.display = 'none';
            $('caShare').addEventListener('click', function () { share(shTxt, SITE + 'tarot-si-o-no.html', this); });
            track('tarot_si_no');
          }, 450);
        });
      });
    }
    var svSN = pmLoad('sn');
    if (svSN) { spread.innerHTML = ''; pmRestore(out, svSN, 'snAgain', [q.parentNode, document.querySelector('.sn-hint')]); } else deal();
  }

  /* ====================== RUNAS ====================== */
  if (tool === 'runas') {
    var R = window.PM_RUNAS, out2 = $('caResult');
    var RX = window.PM_RUNAS_X || {};
    function stone(r, big, rev) {
      var s = '<svg viewBox="-6 -6 52 76" class="rn-svg' + (big ? ' rn-big' : '') + '" aria-hidden="true">';
      r[2].forEach(function (l) { s += '<line x1="' + l[0] + '" y1="' + l[1] + '" x2="' + l[2] + '" y2="' + l[3] + '"/>'; });
      return '<div class="rn-stone"' + (rev ? ' style="transform:rotate(180deg)"' : '') + '>' + s + '</svg></div>';
    }
    function cast(n) {
      var pick = shuffle(R).slice(0, n).map(function (r) { var x = RX[r[0]] || {}; return { r: r, x: x, rev: !!x.i && rnd(10) < 3 }; });
      var pos = n === 1 ? ['Your rune'] : ['Pasado', 'Presente', 'Futuro'];
      var h = '<div class="rn-row">' + pick.map(function (p, i) { return '<div class="rn-cell" style="animation-delay:' + (i * 0.25) + 's">' + stone(p.r, n === 1, p.rev) + '<div class="rn-pos">' + pos[i] + '</div><div class="rn-name">' + p.r[0] + (p.rev ? ' <small>(reversed)</small>' : '') + '</div></div>'; }).join('') + '</div>';
      h += '<div class="ca-list">' + pick.map(function (p, i) {
        var r = p.r, x = p.x, t = '<div class="ca-item"><div class="ca-item-t">' + (n > 1 ? pos[i] + ': ' : '') + r[0] + (p.rev ? ' reversed' : '') + ' <small>(' + r[1] + ')</small></div>';
        if (p.rev) t += '<p>' + x.i + ' <strong>' + r[4] + '</strong></p>';
        else { t += '<p>' + r[3] + ' <strong>' + r[4] + '</strong></p>'; if (x.a) t += '<p class="rn-extra"><em>In love:</em> ' + x.a.replace(/^En el amor,?\s*/, '') + '</p><p class="rn-extra"><em>At work:</em> ' + x.t.replace(/^En el trabajo( y el dinero)?,?\s*/, '') + '</p>'; }
        var x2 = (window.PM_RUNAS_X2 || {})[r[0]];
        if (x2) {
          if (n > 1 && i === 0 && !p.rev) t += '<p class="rn-extra"><em>As the past:</em> ' + x2.p.charAt(0).toUpperCase() + x2.p.slice(1) + '.</p>';
          if (n > 1 && i === 2 && !p.rev) t += '<p class="rn-extra"><em>As the future:</em> ' + x2.f.charAt(0).toUpperCase() + x2.f.slice(1) + '.</p>';
          t += '<p class="rn-extra"><em>' + (p.rev ? 'How to handle it:' : 'Practical advice:') + '</em> ' + (p.rev ? x2.ic : x2.c) + '</p>';
          t += '<p class="rn-extra"><em>For reflection:</em> ' + x2.q + '</p>';
          if (!p.rev) t += '<p class="rn-extra"><em>Affirmation:</em> “' + x2.af + '”</p>';
        }
        return t + '</div>';
      }).join('') + '</div>';
      if (n === 3 && pick[0].x.k) {
        var inv = pick.filter(function (p) { return p.rev; }).length;
        h += '<p class="ca-note" style="text-align:center">Your spread goes from ' + pick[0].x.k + ' (past) to ' + pick[1].x.k + ' (present), and points toward ' + pick[2].x.k + ' (future).' + (inv ? ' Reversed runes point to where it’s best to slow down or review.' : '') + '</p>';
      }
      h += '<div class="ca-actions"><button type="button" class="ca-btn2" id="rnAgain">🔄 Draw again</button><button type="button" class="ca-btn2" id="caShare">📤 Share</button></div>';
      out2.innerHTML = h; out2.hidden = false; scrollTo(out2);
      var rnTxt = 'My runes: ' + pick.map(function (p) { return p.r[0] + (p.rev ? ' (reversed)' : ''); }).join(', ') + '. Do your free rune reading:';
      pmLock('rnAgain'); pmSave('runas', out2.innerHTML, rnTxt, SITE + 'runas.html'); $('rn1').parentNode.style.display = 'none';
      $('caShare').addEventListener('click', function () { share(rnTxt, SITE + 'runas.html', this); });
      track('runas_tirada');
    }
    var svRn = pmLoad('runas');
    if (svRn) pmRestore(out2, svRn, 'rnAgain', [$('rn1').parentNode, document.querySelector('.rn-box .sn-hint')]);
    else { $('rn1').addEventListener('click', function () { cast(1); }); $('rn3').addEventListener('click', function () { cast(3); }); }
  }

  /* ====================== I CHING ====================== */
  if (tool === 'iching') {
    var I = window.PM_ICHING, out3 = $('caResult'), lines = [], board = $('icBoard');
    function hexOf(bits) {
      var lo = bits.slice(0, 3).join(''), up = bits.slice(3, 6).join('');
      return { n: I.table[I.order.indexOf(lo)][I.order.indexOf(up)], lo: I.trig[lo], up: I.trig[up] };
    }
    function drawHex(bits, moving) {
      var s = '<svg viewBox="0 0 120 132" class="ic-hex" aria-hidden="true">';
      for (var i = 0; i < 6; i++) {
        var y = 116 - i * 22, mv = moving && moving[i], col = mv ? '#F08A8C' : '#E9D9A6';
        if (bits[i]) s += '<rect x="6" y="' + y + '" width="108" height="12" rx="2" fill="' + col + '"/>';
        else s += '<rect x="6" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/><rect x="68" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/>';
      }
      return s + '</svg>';
    }
    function renderBoard() {
      var s = '<svg viewBox="0 0 120 132" class="ic-hex" aria-hidden="true">';
      for (var i = 0; i < 6; i++) {
        var y = 116 - i * 22, v = lines[i];
        if (v === undefined) { s += '<rect x="6" y="' + y + '" width="108" height="12" rx="2" fill="none" stroke="rgba(233,217,166,0.25)" stroke-dasharray="4 4"/>'; continue; }
        var col = (v === 6 || v === 9) ? '#F08A8C' : '#E9D9A6';
        s += (v === 7 || v === 9) ? '<rect x="6" y="' + y + '" width="108" height="12" rx="2" fill="' + col + '"/>' : '<rect x="6" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/><rect x="68" y="' + y + '" width="46" height="12" rx="2" fill="' + col + '"/>';
      }
      board.innerHTML = s + '</svg>';
      $('icCount').textContent = lines.length + ' of 6 lines';
      $('icToss').textContent = lines.length < 6 ? '🪙 Cast the coins (' + (lines.length + 1) + '/6)' : '✓ Hexagram complete';
      $('icToss').disabled = lines.length >= 6;
    }
    function toss() {
      if (lines.length >= 6) return;
      var coins = [rnd(2), rnd(2), rnd(2)], v = coins.reduce(function (s, c) { return s + (c ? 3 : 2); }, 0);
      $('icCoins').innerHTML = coins.map(function (c) { return '<span class="ic-coin ' + (c ? 'ic-h' : 'ic-t') + '">' + (c ? 'Cara' : 'Cruz') + '</span>'; }).join('');
      lines.push(v); renderBoard();
      if (lines.length === 6) result();
    }
    function result() {
      var bits = lines.map(function (v) { return v === 7 || v === 9 ? 1 : 0; }), mv = lines.map(function (v) { return v === 6 || v === 9; });
      var H = hexOf(bits), N = I.names[H.n], movIdx = [];
      mv.forEach(function (m, i) { if (m) movIdx.push(i + 1); });
      var h = '<div class="ic-res">' + (($('icQ').value || '').trim() ? '<p class="sn-q">“' + esc($('icQ').value.trim()) + '”</p>' : '') + drawHex(bits, mv) +
        '<div class="ca-kick">Hexagram ' + H.n + '</div><h2>' + N[0] + '</h2><p class="ic-tri">' + H.up[1] + ' on ' + H.lo[1] + '</p><p>' + N[1] + '</p></div>';
      var X = (window.PM_ICHING_X || [])[H.n], TA = window.PM_TRIG_ATTR || {};
      if (X) {
        h += '<div class="ca-item"><div class="ca-item-t">What the hexagram says</div><p>' + X[0] + '</p><p class="rn-extra">Above, ' + H.up[1] + ' (' + (TA[H.up[1]] || '') + '); below, ' + H.lo[1] + ' (' + (TA[H.lo[1]] || '') + '). Their combination defines the character of the situation.</p></div>';
        h += '<div class="ca-item"><div class="ca-item-t">In love</div><p>' + X[1].replace(/^En el amor,?\s*/, '').replace(/^./, function (c) { return c.toUpperCase(); }) + '</p></div>';
        h += '<div class="ca-item"><div class="ca-item-t">At work</div><p>' + X[2].replace(/^En el trabajo,?\s*/, '').replace(/^./, function (c) { return c.toUpperCase(); }) + '</p></div>';
      }
      var XX = (window.PM_ICHING_X2 || {})[H.n];
      if (XX) h += '<div class="ca-item"><div class="ca-item-t">Theme and advice</div><p>The central theme is <strong>' + XX.k + '</strong>. ' + XX.c + '</p><p class="rn-extra"><em>To reflect on:</em> ' + XX.q + '</p></div>';
      if (movIdx.length) {
        var bits2 = bits.map(function (b, i) { return mv[i] ? 1 - b : b; }), H2 = hexOf(bits2), N2 = I.names[H2.n];
        h += '<div class="ca-item"><div class="ca-item-t">Changing lines: ' + movIdx.join(', ') + '</div><p>The red lines are changing: the situation is transforming.</p>' + movIdx.map(function (i) { var X2 = (window.PM_ICHING_X2 || {})[H.n], LT = (window.PM_ICHING_LINE_TXT || {})[i]; var yang = lines[i - 1] === 9; return '<p class="rn-extra">' + (X2 && LT ? LT[yang ? 9 : 6].replace('{k}', X2.k).replace(/tema de (el|los) /,function (m, a) { return a === 'el' ? 'theme of ' : 'theme of '; }) : ((window.PM_ICHING_LINES || [])[i] || '')) + '</p>'; }).join('') + '<p>Where it is heading:</p></div>';
        h += '<div class="ic-res ic-res2">' + drawHex(bits2) + '<div class="ca-kick">It changes into hexagram ' + H2.n + '</div><h2>' + N2[0] + '</h2><p>' + N2[1] + '</p>' + (((window.PM_ICHING_X || [])[H2.n]) ? '<p class="rn-extra">' + window.PM_ICHING_X[H2.n][0] + '</p>' : '') + '</div>';
      } else h += '<p class="ca-note" style="text-align:center">No lines change: the situation is stable and the advice applies as is.</p>';
      h += '<div class="ca-actions"><button type="button" class="ca-btn2" id="icAgain">🔄 New reading</button><button type="button" class="ca-btn2" id="caShare">📤 Share</button></div>';
      out3.innerHTML = h; out3.hidden = false; scrollTo(out3);
      var icTxt = 'The I Ching gave me hexagram ' + H.n + ': ' + N[0] + '. Look up yours for free:';
      pmLock('icAgain'); pmSave('iching', out3.innerHTML, icTxt, SITE + 'i-ching.html');
      $('caShare').addEventListener('click', function () { share(icTxt, SITE + 'i-ching.html', this); });
      track('iching_consulta');
    }
    var svIc = pmLoad('iching');
    if (svIc) pmRestore(out3, svIc, 'icAgain', [$('icQ').parentNode, document.querySelector('.ic-stage'), $('icToss'), $('icAll')]);
    else { $('icToss').addEventListener('click', toss); $('icAll').addEventListener('click', function () { while (lines.length < 6) toss(); }); renderBoard(); }
  }
  /* ====================== ÁNGEL DE LA GUARDA ====================== */
  if (tool === 'angel') {
    var AN = window.PM_ANGELES, out4 = $('caResult');
    var CHOIRS = ['Serafines', 'Querubines', 'Tronos', 'Dominaciones', 'Potencias', 'Virtudes', 'Principados', 'Archangels', 'Angels'];
    var MES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    function k(m, d) { return m * 100 + d; }
    function find(m, d) {
      for (var i = 0; i < AN.length; i++) { var s = k(AN[i][1][0], AN[i][1][1]), e = k(AN[i][2][0], AN[i][2][1]), x = k(m, d); if (s <= e ? (x >= s && x <= e) : (x >= s || x <= e)) return i; }
      return 0;
    }
    try { var sv = JSON.parse(localStorage.getItem('pmCarta') || 'null'); if (sv && sv.date) $('agDate').value = sv.date; } catch (e) {}
    $('caForm').addEventListener('submit', function (e) {
      e.preventDefault(); $('caError').textContent = '';
      var v = $('agDate').value; if (!v) { $('caError').textContent = 'Enter your date of birth.'; return; }
      var p = v.split('-').map(Number), i = find(p[1], p[2]), A = AN[i], num = ((i - 16 + 72) % 72) + 1, choir = CHOIRS[Math.floor((num - 1) / 8)];
      var range = A[1][1] + ' ' + MES[A[1][0] - 1] + ' to ' + A[2][1] + ' ' + MES[A[2][0] - 1];
      var h = '<div class="ag-res"><div class="ag-halo">👼</div><div class="ca-kick">Your guardian angel is</div><h2>' + A[0] + '</h2>' +
        '<div class="ca-pills"><span>Angel no. ' + num + ' of 72</span><span>Choir of the ' + choir + '</span>' + (window.PM_ANGEL_REFS ? '<span>' + window.PM_ANGEL_REFS[num - 1] + '</span>' : '') + '<span>' + range + '</span></div>' +
        '<p class="ag-txt">' + A[0] + ' ' + A[3] + '.</p></div>' +
        '<div class="ca-list"><div class="ca-item"><div class="ca-item-t">How to connect with ' + A[0] + '</div><p>Find a quiet moment, light a white candle if you wish, and repeat its name softly three times. Then tell it in your own words what you need. Many people do this during their period of influence (from ' + range + ') and the day of their birthday.</p></div>' +
        '<div class="ca-item"><div class="ca-item-t">A simple prayer</div><p class="ag-pray">“' + A[0] + ', my guardian angel, thank you for accompanying me. Help me today to see clearly, to act with love, and to recognize your signs on my path. So be it.”</p></div></div>' +
        '<div class="ca-actions"><button type="button" class="ca-btn2" id="caShare">📤 Share</button></div>' +
        '<p class="ca-more">Seeing repeated numbers like 111 or 444? Read what <a href="../blog/numeros-angelicales-significado.html">angel numbers →</a> mean.</p>';
      out4.innerHTML = h; out4.hidden = false; scrollTo(out4);
      $('caShare').addEventListener('click', function () { share('My guardian angel is ' + A[0] + '. Discover yours for free:', SITE + 'angel-de-la-guarda.html', this); });
      track('angel_guarda');
    });
  }
})();
;
